-- The Jira filter source (`jira.filter.new_issue`): a polling automation and what it remembers
-- between polls (`docs/automations.md` §3.2). The tables below are generated by
-- `prisma migrate diff`; the constraints after them are hand-written because Prisma cannot express
-- them (the skill `prisma-pgvector-hnsw`).

-- CreateTable
CREATE TABLE "automation_poll_states" (
    "automation_id" UUID NOT NULL,
    "baselined_at" TIMESTAMPTZ,
    "last_polled_at" TIMESTAMPTZ,
    "last_error" TEXT,
    "lease_until" TIMESTAMPTZ,
    "updated_at" TIMESTAMPTZ NOT NULL,

    CONSTRAINT "automation_poll_states_pkey" PRIMARY KEY ("automation_id")
);

-- CreateTable
CREATE TABLE "automation_seen_issues" (
    "automation_id" UUID NOT NULL,
    "issue_key" TEXT NOT NULL,
    "first_seen_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "automation_seen_issues_pkey" PRIMARY KEY ("automation_id","issue_key")
);

-- AddForeignKey
ALTER TABLE "automation_poll_states" ADD CONSTRAINT "automation_poll_states_automation_id_fkey" FOREIGN KEY ("automation_id") REFERENCES "automations"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "automation_seen_issues" ADD CONSTRAINT "automation_seen_issues_automation_id_fkey" FOREIGN KEY ("automation_id") REFERENCES "automations"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- `automations_source_known` cannot be altered in place, so it is replaced with the source added.
ALTER TABLE "automations" DROP CONSTRAINT "automations_source_known";
DO $$ BEGIN
  ALTER TABLE "automations" ADD CONSTRAINT "automations_source_known"
    CHECK ("source" IN ('github.workflow_run.failed', 'github.issues.labeled', 'inbound.event', 'github.pull_request.feedback', 'jira.filter.new_issue'));
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

-- A Jira filter automation holds a non-empty JQL string and lives on a repository. A CHECK that
-- evaluates to NULL passes; COALESCE makes a missing key fail instead, as in the sibling per-source
-- checks. The 2000-character bound is the source's and is left to the API.
DO $$ BEGIN
  ALTER TABLE "automations" ADD CONSTRAINT "automations_jira_filter_filters"
    CHECK ("source" <> 'jira.filter.new_issue' OR COALESCE(
      "connection_id" IS NOT NULL
      AND jsonb_typeof("filters") = 'object'
      AND "filters" ? 'jql'
      AND jsonb_typeof("filters"->'jql') = 'string'
      AND length(btrim("filters"->>'jql')) > 0,
      false
    ));
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

-- One issue has one spelling in the seen set, so a key that differs only in case is the same key.
DO $$ BEGIN
  ALTER TABLE "automation_seen_issues" ADD CONSTRAINT "automation_seen_issues_key_lowercase"
    CHECK ("issue_key" = lower("issue_key"));
EXCEPTION WHEN duplicate_object THEN NULL; END $$;
